def _get_multidict_value(
    field: ModelField,
    received_params: Union[Dict[str, Any], ImmutableMultiDict],
    alias: Optional[str] = None,
) -> Any:
    if not received_params:
        return None
    if not alias:
        alias = field.alias
    if isinstance(received_params, dict):
        return received_params.get(alias)
    value = received_params.get(alias)
    if value is None:
